const MS=window.MarketStore;
const marketPages={categories:'分类目录管理',frequency:'分类使用频次统计',keywords:'应用关键词库管理',searchHistory:'检索历史记录管理',searchApi:'检索服务接口提供',audit:'审核管理'};
const marketSearchTabs=['categories','frequency','keywords','searchHistory','searchApi'];
amkTabs.push(...marketSearchTabs);Object.assign(amkTitles,marketPages);marketSearchTabs.forEach(t=>amkNavReq[t]='appmarket.search.'+t);
let marketQuery='',marketLevel='全部',marketQueue='待审核',marketAuditType=new URL(location.href).searchParams.get('auditType')||'全部';
const marketMark=(tab,el)=>{const id=tab==='audit'?'appmarket.admin.audit':tab==='review'?'appmarket.admin.audit.dialog':'appmarket.search.'+tab;return req(id,id+'.'+el)};
const marketNodeParent=n=>n.level===3?n.parent:(MS.read().nodes.find(x=>x.id===n.parent)?.name||'—');
const marketLevelName=n=>n.level===1?'一级目录':n.level===2?'二级目录':'三级标签';
function marketNav(){return `<div class="ai-nav-title">应用市场后台管理系统</div><div class="ais-group">应用搜索<span>⌄</span></div>${marketSearchTabs.map(t=>`<button class="ai-nav-item ${amkTab===t?'active':''}" onclick="amkOpen('${t}')" ${marketMark(t,'nav')}>${marketPages[t]}</button>`).join('')}<div class="ais-group">审核管理<span>⌄</span></div><button class="ai-nav-item ${amkTab==='audit'?'active':''}" onclick="amkOpen('audit')">审核管理</button><div class="ais-group">应用市场管理<span>⌄</span></div>${amkTabs.filter(t=>!marketSearchTabs.includes(t)&&t!=='audit').map(t=>`<button class="ai-nav-item ${amkTab===t?'active':''}" onclick="amkOpen('${t}')">${amkTitles[t]}</button>`).join('')}<button class="ai-back" onclick="amkBackLaunch()">⇤ 返回快捷入口</button>`;}
const marketPreviousRender=amkRender;
amkRender=function(){
 if(!(marketSearchTabs.includes(amkTab)||amkTab==='audit')){marketPreviousRender();$('#sidebar').innerHTML=marketNav();return;}
 document.querySelector('header b').textContent='应用市场后台管理系统';$('#sidebar').innerHTML=marketNav();
 $('#main').innerHTML=`<div class="systemtabs"><span onclick="amkBackLaunch()">首页</span><span class="selected">● 应用市场后台管理系统</span></div><div class="ai-page amk-page market-admin-page" data-req-page="appmarket-${amkTab}" data-req-surface="${amkTab==='audit'?'appmarket.admin.audit':'appmarket.search.'+amkTab}" data-req-title="${marketPages[amkTab]}"><div class="crumb">应用市场后台管理系统 / ${amkTab==='audit'?'审核管理':'应用搜索 / '+marketPages[amkTab]}</div><div id="amk-content"></div></div>`;
 marketContent();
};
function marketFilter(extra=''){return `<form id="market-admin-query" class="market-admin-filters" ${marketMark(amkTab,'filters')}><label>关键词<input name="keyword" value="${esc(marketQuery)}" aria-label="关键词"></label>${extra}<button class="btn primary">查询</button><button class="btn" type="button" onclick="marketQuery='';marketLevel='全部';if(amkTab==='audit')marketSetType('全部');else marketContent()">重置</button></form>`;}
function marketTable(title,heads,rows,action=''){return `<section class="market-admin-panel" ${marketMark(amkTab,'list')}><div class="ai-list-head"><h3>${title}</h3>${action}</div>${amkTable(heads,rows.length?rows.join(''):`<tr><td colspan="${heads.length}" style="text-align:center;padding:40px">暂无数据</td></tr>`,'market-working-rows')}<div class="market-count">共 ${rows.length} 条</div></section>`;}
function marketContent(){({categories:marketCategories,frequency:marketFrequency,keywords:marketKeywords,searchHistory:marketSearchHistory,searchApi:marketSearchApi,audit:marketAuditList})[amkTab]?.();}
function marketCategories(){
 const d=MS.read(),nodes=d.nodes.filter(n=>(marketLevel==='全部'||marketLevelName(n)===marketLevel)&&(!marketQuery||(n.name+' '+marketNodeParent(n)).includes(marketQuery)));
 $('#amk-content').innerHTML=marketFilter(`<label>目录层级<select name="level">${['全部','一级目录','二级目录','三级标签'].map(x=>`<option ${x===marketLevel?'selected':''}>${x}</option>`).join('')}</select></label>`)+marketTable('分类目录',['序号','节点名称','目录层级','上级目录 / 标签维度','审核状态','操作'],nodes.map((n,i)=>{const pending=d.requests.some(r=>r.target===n.id&&r.state==='待审核');return amkRow([`<b>${esc(n.name)}</b>`,marketLevelName(n),esc(marketNodeParent(n)),amkBadge(pending?'变更审核中':'已审核',pending?'orange':'green'),`<div class="market-actions"><button onclick="marketCategoryDetail('${n.id}')">详情</button>${pending?'':`<button onclick="marketCategoryForm('编辑','${n.id}')">编辑</button><button onclick="marketCategoryForm('调整','${n.id}')">调整</button><button onclick="marketCategoryForm('合并','${n.id}')">合并</button><button onclick="marketCategoryDelete('${n.id}')">删除</button>`}</div>`],i)}),`<button class="btn primary" onclick="marketCategoryForm('新增')" ${marketMark('categories','actions')}>新增节点</button>`);
}
function marketCategoryDetail(id){const n=MS.read().nodes.find(n=>n.id===id);amkDialog('分类节点详情',`<section ${marketMark('categoryDetail','info')}>${amkKv([['节点名称',n.name],['目录层级',marketLevelName(n)],['上级目录 / 标签维度',marketNodeParent(n)]])}</section>`,'<button class="btn" onclick="marketClose()">关闭</button>','appmarket.search.categoryDetail.dialog');}
function marketClose(){$('#overlay').innerHTML='';}
function marketCategoryForm(action,id){
 const nodes=MS.read().nodes,n=nodes.find(n=>n.id===id)||{name:'',level:1,parent:''};
 amkDialog(action+'分类节点',`<form id="market-category-form" data-id="${id||''}" data-mode="${action}" class="market-form"><section ${marketMark('categoryEdit','fields')}><label>节点名称<input name="name" value="${esc(n.name)}" required ${action==='合并'?'readonly':''}></label><label>目录层级<select name="level" ${id?'disabled':''}>${[1,2,3].map(v=>`<option value="${v}" ${v===n.level?'selected':''}>${marketLevelName({level:v})}</option>`).join('')}</select></label><div id="market-category-parent"></div></section><section ${marketMark('categoryEdit','actions')}><p class="market-error" role="alert"></p><button class="btn primary" type="submit">提交变更审核</button></section></form>`,'<button class="btn" onclick="marketClose()">取消</button>','appmarket.search.categoryEdit.dialog');
 marketCategoryParents(n,action);
}
function marketCategoryParents(n,action){const d=MS.read();const level=Number(document.querySelector('#market-category-form [name=level]').value);const dest=action==='合并'?d.nodes.filter(x=>x.id!==n.id&&x.level===level&&(level!==3||x.parent===n.parent)):d.nodes.filter(x=>x.level===1);$('#market-category-parent').innerHTML=action==='合并'?`<label>合并至<select name="mergeTo" required>${dest.map(x=>`<option value="${x.id}">${esc(x.name)} / ${esc(marketNodeParent(x))}</option>`).join('')}</select></label>`:level===2?`<label>上级目录<select name="parent" required>${dest.map(x=>`<option value="${x.id}" ${x.id===n.parent?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:level===3?`<label>标签维度<select name="parent">${[...new Set(d.nodes.filter(x=>x.level===3).map(x=>x.parent))].map(x=>`<option ${x===n.parent?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`:'';}
function marketCategoryDelete(id){const d=MS.read(),n=d.nodes.find(x=>x.id===id);if(d.nodes.some(x=>x.parent===id)){toast('请先调整或合并下级节点');return;}if(MS.publicApps().some(a=>n.level===1?a.l1===n.name:n.level===2?a.l2===n.name&&a.l1===marketNodeParent(n):a.tags.includes(n.parent+'·'+n.name))){toast('该节点关联应用，请先调整或合并');return;}amkDialog('删除分类节点',`<section ${marketMark('categoryDelete','info')}><p>确认删除「${esc(n.name)}」？</p></section><section ${marketMark('categoryDelete','actions')}><button class="btn primary" onclick="marketSubmitDelete('${id}')">提交删除审核</button></section>`,'<button class="btn" onclick="marketClose()">取消</button>','appmarket.search.categoryDelete.dialog');}
function marketSubmitDelete(id){try{const n=MS.read().nodes.find(x=>x.id===id);MS.submit('分类目录变更','删除',id,n,null);marketClose();marketContent();toast('已提交审核');}catch(x){toast(x.message);}}
function marketFrequency(){const d=MS.read(),rows=d.nodes.filter(n=>!marketQuery||(n.name+' '+marketNodeParent(n)).includes(marketQuery)).map(n=>({...n,count:d.searches.filter(s=>n.level===1?s.l1===n.name:n.level===2?s.l2===n.name&&s.l1===marketNodeParent(n):s.tags.includes(n.parent+'·'+n.name)).length})).sort((a,b)=>b.count-a.count);const max=Math.max(1,...rows.map(n=>n.count));$('#amk-content').innerHTML=marketFilter()+marketTable('分类使用频次',['序号','分类节点','目录层级','上级目录 / 标签维度','使用次数'],rows.map((n,i)=>amkRow([esc(n.name),marketLevelName(n),esc(marketNodeParent(n)),`${n.count}<div class="market-usage-bars"><i style="width:${n.count/max*100}%"></i></div>`],i)));}
function marketKeywords(){const d=MS.read(),apps=MS.publicApps().filter(a=>!marketQuery||(a.name+' '+(d.keywords[a.id]||[]).join(' ')).includes(marketQuery));$('#amk-content').innerHTML=marketFilter()+marketTable('应用关键词库',['序号','应用名称','关键词','操作'],apps.map((a,i)=>amkRow([esc(a.name),(d.keywords[a.id]||[]).map(esc).join('、')||'—',`<div class="market-actions"><button onclick="marketKeywordEdit('${a.id}')">编辑关键词</button><button onclick="marketKeywordEdit('${a.id}',true)">自动标注</button></div>`],i)));}
function marketSuggestions(a){const words=[...new Set(MS.read().nodes.map(n=>n.name).concat(['接入连接器','身份认证','传输加密','目录同步','数据交换','数据建模','质量校验']))];return words.filter(w=>(a.name+' '+a.desc).includes(w));}
function marketKeywordEdit(id,auto=false){const a=MS.publicApps().find(a=>a.id===id),d=MS.read(),suggestions=marketSuggestions(a);amkDialog(auto?'关键词自动标注':'编辑应用关键词',`<form class="market-form" id="market-keyword-form" data-id="${id}"><section ${marketMark('keywordEdit','manual')}><label>应用名称<input value="${esc(a.name)}" readonly></label><label>关键词<input name="keywords" value="${esc((d.keywords[id]||[]).join('、'))}"></label></section><section ${marketMark('keywordEdit','suggestions')}><h3>推荐关键词</h3><div class="market-chip-group">${suggestions.length?suggestions.map(w=>`<label><input type="checkbox" name="suggestion" value="${esc(w)}" ${auto?'checked':''}>${esc(w)}</label>`).join(''):'暂无推荐关键词'}</div></section><section ${marketMark('keywordEdit','actions')}><p class="market-error" role="alert"></p><button class="btn primary" type="submit">保存</button></section></form>`,'<button class="btn" onclick="marketClose()">取消</button>','appmarket.search.keywordEdit.dialog');}
function marketSearchHistory(){const rows=MS.read().searches.filter(r=>!marketQuery||(r.query+' '+r.tags.join(' ')).includes(marketQuery));$('#amk-content').innerHTML=marketFilter()+marketTable('检索历史记录',['序号','检索关键词','标签组合','分类条件','检索用户','检索时间','结果数','操作'],rows.map((r,i)=>amkRow([esc(r.query||'—'),esc(r.tags.join('、')||'—'),esc([r.l1,r.l2].filter(x=>x!=='全部').join(' / ')||'全部'),r.user,r.time,r.count,`<div class="market-actions"><button onclick="marketHistoryDetail('${r.id}')">详情</button></div>`],i)));}
function marketHistoryDetail(id){const r=MS.read().searches.find(r=>r.id===id);amkDialog('检索记录详情',`<section ${marketMark('historyDetail','info')}>${amkKv([['关键词',r.query||'—'],['标签组合',r.tags.join('、')||'—'],['一级目录',r.l1],['二级目录',r.l2],['检索用户',r.user],['检索时间',r.time],['结果数',String(r.count)]])}</section>`,'<button class="btn" onclick="marketClose()">关闭</button>','appmarket.search.historyDetail.dialog');}
function marketSearchApi(){const source=(window.AM_ITEMS||[]).find(r=>r.item.includes('检索服务接口'));$('#amk-content').innerHTML=marketFilter()+marketTable('检索服务接口',['序号','名称','需求出处'],(!marketQuery||'检索服务接口提供'.includes(marketQuery))?[amkRow(['检索服务接口提供',esc(source?.src||'5.5.2.2.1 应用检索')],0)]:[]);}
function marketAuditList(){const all=MS.read().requests,queue=all.filter(r=>marketQueue==='待审核'?r.state==='待审核':r.state!=='待审核'),rows=queue.filter(r=>(marketAuditType==='全部'||r.type===marketAuditType)&&(!marketQuery||[r.after?.name,r.before?.name,r.applicant,r.action].join(' ').includes(marketQuery)));$('#amk-content').innerHTML=`<div class="market-audit-tabs" ${marketMark('audit','queue')}>${['待审核','已审核'].map(q=>`<button class="${q===marketQueue?'active':''}" onclick="marketQueue='${q}';marketQuery='';marketContent()">${q}</button>`).join('')}</div><section class="market-audit-types" ${marketMark('audit','types')}>${['全部','分类目录变更','应用上架'].map(t=>`<button class="${marketAuditType===t?'active':''}" onclick="marketSetType('${t}')">${t}<b>${queue.filter(r=>t==='全部'||r.type===t).length}</b></button>`).join('')}</section>`+marketFilter()+marketTable('审核列表',['序号','申请名称','审核类型','申请事项','申请人','申请时间','状态','操作'],rows.map((r,i)=>amkRow([esc(r.after?.name||r.before?.name||'—'),r.type,r.action,esc(r.applicant),r.submitted,amkBadge(r.state,r.state==='已通过'?'green':'orange'),`<button class="btn" onclick="marketReview('${r.id}')">${r.state==='待审核'?'审核':'详情'}</button>`],i)));}
function marketSetType(type){marketAuditType=type;marketQuery='';const u=new URL(location.href);if(type==='全部')u.searchParams.delete('auditType');else u.searchParams.set('auditType',type);history.replaceState(null,'',u);marketContent();}
function marketReview(id){const r=MS.read().requests.find(r=>r.id===id),a=r.after||r.before,mark=x=>marketMark('review',x),pending=r.state==='待审核';const pairs=r.type==='分类目录变更'?[['申请事项',r.action],['节点名称',a?.name||'—'],['目录层级',marketLevelName(a||{level:1})],['原上级目录 / 维度',r.before?marketNodeParent(r.before):'—'],['新上级目录 / 维度',r.after?.mergeTo?(MS.read().nodes.find(n=>n.id===r.after.mergeTo)?.name||'—'):r.after?marketNodeParent(r.after):'—']]:[['申请事项',r.action],['应用名称',a.name],['原版本',r.before?.version||'—'],['申请版本',a.version],['供应商',a.vendor],['功能描述',a.desc],['标签',a.tags.join('、')||'—'],['注销说明',a.cancelReason||'—'],['安装包',a.package||'—'],['使用手册',a.manual||'—'],['合规性证明',a.complianceFile||'—']];
 $('#overlay').innerHTML=`<div class="identity-audit-veil"><section class="identity-audit-dialog" role="dialog" aria-modal="true" aria-label="${r.type}审核" data-req-page="appmarket-audit" data-req-surface="appmarket.admin.audit.dialog" data-req-layer="dialog" data-req-title="${r.type}审核"><header class="identity-audit-header" ${mark('context')}><div><span class="identity-audit-eyebrow">应用市场后台管理系统 · 审核管理</span><h1>${r.type}审核 <span class="identity-audit-state">${r.state}</span></h1></div><button class="identity-audit-close" aria-label="关闭审核弹窗" onclick="marketClose()">×</button></header><div class="identity-audit-layout"><div class="identity-audit-information"><section class="identity-audit-focus" ${mark('subject')}><span class="identity-audit-focus-icon">▦</span><div><h2>${esc(a?.name||'分类变更')}</h2><p>申请人：${esc(r.applicant)}</p><p>申请时间：${r.submitted}</p></div></section><section class="identity-audit-section" ${mark('request')}><div class="identity-audit-section-title"><h2>申请信息</h2></div><div class="identity-audit-request"><dl class="market-modal-info">${pairs.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></div></section></div><div class="identity-audit-side"><aside class="identity-audit-decision" ${mark('decision')}><div class="identity-audit-decision-heading"><span>审核工作区</span><h2>${pending?'请完成审核':'审核结果'}</h2></div>${pending?`<form id="market-review-form-admin" data-id="${id}" class="market-form"><fieldset><legend>审核结果</legend><label class="identity-audit-choice"><input type="radio" name="result" value="已通过" checked>通过</label><label class="identity-audit-choice"><input type="radio" name="result" value="驳回">驳回</label></fieldset><label class="identity-audit-opinion">审核意见<textarea name="opinion" maxlength="300"></textarea></label><p class="market-error" role="alert"></p><section ${mark('actions')}><button class="btn primary" type="submit">提交审核</button></section></form>`:`<div class="identity-audit-read-result"><dl><dt>审核结果</dt><dd>${r.state}</dd><dt>审核人</dt><dd>当前管理员</dd><dt>审核时间</dt><dd>${r.reviewedAt}</dd><dt>审核意见</dt><dd>${esc(r.opinion||'—')}</dd></dl></div>`}</aside><section class="identity-audit-section identity-flow-section" ${mark('flow')}><div class="identity-audit-section-title"><h2>流程信息</h2></div><div class="identity-flow-body"><ol class="identity-flow"><li class="done"><span class="identity-flow-marker">✓</span><div class="identity-flow-content"><strong>提交申请</strong><p>${r.submitted}</p></div></li><li class="${pending?'current':'done'}"><span class="identity-flow-marker">2</span><div class="identity-flow-content"><strong>${pending?'待审核':r.state}</strong><p>${pending?'当前管理员':r.reviewedAt}</p></div></li></ol></div></section></div></div></section></div>`;
}
document.addEventListener('change',e=>{if(e.target.matches('#market-category-form [name=level]'))marketCategoryParents({id:'',parent:''},'新增');});
document.addEventListener('submit',e=>{
 const f=e.target;if(!['market-admin-query','market-category-form','market-keyword-form','market-review-form-admin'].includes(f.id))return;e.preventDefault();const data=new FormData(f);
 try{
  if(f.id==='market-admin-query'){marketQuery=String(data.get('keyword')||'').trim();marketLevel=String(data.get('level')||'全部');marketContent();return;}
  if(f.id==='market-category-form'){const d=MS.read(),before=d.nodes.find(n=>n.id===f.dataset.id),level=before?.level||Number(data.get('level')),name=String(data.get('name')).trim(),parent=level===1?'':String(data.get('parent')||before?.parent||'');if(!name)throw Error('请填写节点名称');const action=f.dataset.mode;const after=action==='合并'?{...before,mergeTo:String(data.get('mergeTo')||'')}:{id:before?.id||MS.id(),name,level,parent,original:before?.original||name};if(action==='合并'&&!after.mergeTo)throw Error('请选择合并目标');if(action!=='合并'&&d.nodes.some(n=>n.id!==before?.id&&n.level===level&&n.parent===parent&&n.name===name))throw Error('同一上级下已有同名节点');MS.submit('分类目录变更',action,before?.id||after.id,before||null,after);}
  if(f.id==='market-keyword-form'){const d=MS.read();d.keywords[f.dataset.id]=[...new Set(String(data.get('keywords')||'').split(/[、，,\n]/).map(x=>x.trim()).filter(Boolean).concat(data.getAll('suggestion')))];MS.write(d);}
  if(f.id==='market-review-form-admin')MS.decide(f.dataset.id,String(data.get('result')),String(data.get('opinion')||''));
  marketClose();marketContent();toast(f.id==='market-category-form'?'已提交变更审核':f.id==='market-review-form-admin'?'审核已提交':'已保存');
 }catch(x){const el=f.querySelector('[role=alert]');if(el)el.textContent=x.message;else toast(x.message);}
});
(function(){const q=new URL(location.href).searchParams;if(q.get('system')==='appmarket')amkOpen(q.get('view')||'listing');})();
